function Overview({s,current,week,navigate}:{s:State;current?:Week;week:string;navigate:(v:string)=>void}){
 const closed=s.weeks.filter(w=>w.status==='closed'),tot=closed.reduce((n,w)=>n+metrics(s,w).total,0),done=closed.reduce((n,w)=>n+metrics(s,w).done,0),ppc=pct(done,tot),open=s.constraints.filter(c=>!c.resolvedOn),readyTasks=s.tasks.filter(t=>ready(s,t)),completed=s.tasks.filter(t=>remaining(s,t)===0),m=current?metrics(s,current):null;
 return <><div className="overviewbanner"><div><span className="eyebrow">MAKE EVERY HANDOFF COUNT</span><h2>{s.name}</h2><p>{s.location||'Your project workspace'} <span>·</span> {s.client||'Lean project delivery'}</p></div><div className="bannerweek"><span>PLANNING WEEK</span><strong>{dateRange(week)}</strong><Badge tone="light">{current?.status??'Plan not started'}</Badge></div></div><div className="stats"><Stat label="Plan reliability" value={ppc===null?'—':ppc+'%'} detail={tot?`${done} of ${tot} closed-week promises met`:'No closed-week promises yet'} icon={<ChartNoAxesCombined size={18}/>}/><Stat label="Ready to work" value={readyTasks.length} detail={`${s.tasks.filter(t=>t.pull).length} activities in the pull plan`} icon={<CheckCircle2 size={18}/>}/><Stat label="Open constraints" value={open.length} detail={<span className={open.some(c=>c.due<today())?'warningtext':''}>{open.filter(c=>c.due<today()).length} overdue removal dates</span>} icon={<ShieldCheck size={18}/>}/><Stat label="Scope complete" value={`${completed.length} / ${s.tasks.length}`} detail="Activities · measured against total scope" icon={<Layers size={18}/>}/></div>
 <div className="overviewgrid"><Panel title="This week’s promises" detail={dateRange(week)} action={<button className="textbutton" onClick={()=>navigate('weekly')}>Open work plan <ArrowUpRight size={16}/></button>}><div className="promiseoverview"><div className="ring" style={{background:`conic-gradient(var(--accent) ${(m?.ppc??0)*3.6}deg, var(--border) 0deg)`}}><div><strong>{m?.ppc===null||!m?'—':m.ppc+'%'}</strong><span>PPC PREVIEW</span></div></div><div><h3>{m?.done??0} promises met</h3><p>of {m?.total??0} planned for this week</p><small>100% complete, by the promised date.</small></div></div><div className="promiselist">{current?.commitments.slice(0,4).map(c=>{const t=findTask(s,c.taskId),actual=commitmentActual(s,c);return <div className="promiserow" key={c.id}><span className="trade-dot"/><div><strong>{t.name}</strong><small>{c.owner}</small></div><span>{fmt(actual)} / {fmt(c.quantity)} <small>{t.unit}</small></span><Badge tone={commitmentActual(s,c,c.due)>=c.quantity?'teal':'neutral'}>{commitmentActual(s,c,c.due)>=c.quantity?'Met':'In progress'}</Badge></div>})}{!current?.commitments.length&&<Empty title="Make the week intentional" detail="Allocate ready work, then create and freeze your weekly promises." action={<button onClick={()=>navigate('weekly')}>Build this week’s plan</button>}/>}</div></Panel>
 <Panel title="Needs your attention" detail="Clear the path for upcoming work" action={<Badge tone="amber">{open.length} open</Badge>}>{open.slice(0,4).map(c=><div className="attentionrow" key={c.id}><span className="attentionicon"><AlertTriangle size={16}/></span><div><strong>{c.description}</strong><small>{c.owner} · {findTask(s,c.taskId).area}</small><span className="due">Required {df(c.due)}</span></div></div>)}{!open.length&&<div className="allclear"><CheckCircle2 size={30}/><h3>A clear path ahead</h3><p>No open constraints recorded. Keep checking readiness with the team.</p></div>}<button className="panelbottom" onClick={()=>navigate('constraints')}>View constraint log <ArrowRight size={15}/></button></Panel></div>
 <div className="overviewgrid lower"><Panel title="The planning conversation" detail="One connected cycle. Five deliberate conversations."><div className="conversation">{[{k:'SHOULD',s:'Master & pull plan',n:'pull',v:s.tasks.filter(t=>t.pull).length+' activities'},{k:'CAN',s:'Make work ready',n:'lookahead',v:readyTasks.length+' ready'},{k:'WILL',s:'Weekly promises',n:'weekly',v:(current?.commitments.length??0)+' promises'},{k:'DID',s:'Daily check-in',n:'daily',v:s.entries.filter(e=>current?.commitments.some(c=>c.id===e.commitmentId)).length+' entries'},{k:'LEARN',s:'Close the loop',n:'analytics',v:closed.length+' weeks closed'}].map((x,i)=><button onClick={()=>navigate(x.n)} key={x.k}><span className="stepnum">0{i+1}</span><strong>{x.k}</strong><p>{x.s}</p><small>{x.v}</small><ArrowUpRight size={14}/></button>)}</div></Panel><Panel title="Next milestones" detail="Keep the destination visible">{s.milestones.slice(0,3).map(m=><div className="nextmilestone" key={m.id}><Flag size={17}/><div><strong>{m.name}</strong><small>{m.owner}</small></div><strong>{df(m.date)}</strong></div>)}{!s.milestones.length&&<div className="pad"><p className="muted">Define your first phase outcome.</p><button onClick={()=>navigate('master')}>Set milestones <ArrowRight size={14}/></button></div>}</Panel></div></>;
}
function CommitmentTable({state,week,action}:{state:State;week?:Week;action:(c:Week['commitments'][number])=>ReactNode}){return <Panel title="Weekly commitment register" detail="One promise per activity per week. Completion is counted as a binary outcome.">{week?.commitments.length?<div className="tablewrap"><table><thead><tr><th>Activity</th><th>Last planner</th><th>Promised</th><th>Actual by due date</th><th>Due</th><th>Status</th><th/></tr></thead><tbody>{week.commitments.map(c=>{const t=findTask(state,c.taskId),a=commitmentActual(state,c,c.due);return <tr key={c.id}><td><strong>{t.name}</strong><small>{t.trade} · {t.area}</small></td><td>{c.owner}</td><td>{fmt(c.quantity)} {t.unit}</td><td>{fmt(a)} {t.unit}</td><td>{df(c.due)}</td><td><Badge tone={a>=c.quantity?'teal':c.due<today()?'amber':'neutral'}>{a>=c.quantity?'Met':c.due<today()?'Missed':'Pending'}</Badge></td><td>{action(c)}</td></tr>})}</tbody></table></div>:<Empty title="No promises yet" detail="Create a lookahead allocation, clear the activity’s constraints, and make a commitment."/>}</Panel>}
function Analytics({s,week}:{s:State;week?:Week}){const closed=s.weeks.filter(w=>w.status==='closed').sort((a,b)=>a.key.localeCompare(b.key)),m=week?metrics(s,week):null,reasonsMap:Record<string,number>={};closed.forEach(w=>w.commitments.forEach(c=>{if(commitmentActual(s,c,c.due)<c.quantity)reasonsMap[c.reason]=(reasonsMap[c.reason]??0)+1;}));const totals=unitTotals(s);return <><div className="stats three"><Stat label={`PPC · ${week?.status==='closed'?'final':'preview'}`} value={m?.ppc===null||!m?'—':m.ppc+'%'} detail={`${m?.done??0} / ${m?.total??0} promises completed on time`} icon={<ChartNoAxesCombined size={18}/>}/><Stat label="Tasks anticipated" value={m?.ta===null||!m?'—':m.ta+'%'} detail="Promises allocated before their week began" icon={<CalendarRange size={18}/>}/><Stat label="Tasks made ready" value={m?.tmr===null||!m?'—':m.tmr+'%'} detail="Ready / allocated activities when week started" icon={<ShieldCheck size={18}/>}/></div><div className="overviewgrid"><Panel title="Weekly plan reliability" detail="Closed weeks only. Each bar is completed-on-time promises / frozen promises.">{closed.length?<div className="barchart">{closed.map(w=>{const x=metrics(s,w);return <div className="baritem" key={w.key}><strong>{x.ppc}%</strong><div><i style={{height:(x.ppc??0)+'%'}}/></div><small>{df(w.key)}</small></div>})}</div>:<Empty title="Reliability grows week by week" detail="Close your first week to start the trend. Active weeks remain previews."/>}</Panel><Panel title="Reasons for variance" detail="Count missed promises, then act on the recurring causes.">{Object.entries(reasonsMap).sort((a,b)=>b[1]-a[1]).map(([reason,n])=><div className="reasonrow" key={reason}><strong>{reason}</strong><div className="progress"><i style={{width:n/Math.max(...Object.values(reasonsMap))*100+'%'}}/></div><span>{n}</span></div>)}{!Object.keys(reasonsMap).length&&<p className="pad muted">No variance recorded in closed weeks.</p>}</Panel></div><Panel title="Scope ledger · by unit" detail="Cubic metres, tonnes and square metres are never added together."><div className="tablewrap"><table><thead><tr><th>Unit</th><th>Total scope</th><th>Cumulative actual</th><th>Remaining</th></tr></thead><tbody>{Object.entries(totals.total).map(([u,t])=><tr key={u}><td>{u}</td><td>{fmt(t)}</td><td>{fmt(totals.actual[u]??0)}</td><td>{fmt(t-(totals.actual[u]??0))}</td></tr>)}</tbody></table></div></Panel><Panel title="Improvement actions" detail="Specific actions from missed promises in closed weeks.">{closed.flatMap(w=>w.commitments.filter(c=>c.learning).map(c=><div className="learningrow" key={c.id}><Badge tone="amber">{c.reason}</Badge><div><strong>{findTask(s,c.taskId).name}</strong><p>{c.learning}</p><small>Week of {df(w.key)} · {c.owner}</small></div></div>))}{!closed.some(w=>w.commitments.some(c=>c.learning))&&<p className="pad muted">Record reasons and improvement actions during closeout.</p>}</Panel><div className="callout"><BookOpen size={18}/><div><strong>Metric definitions are explicit.</strong><p>PPC follows the LCI binary completion rule. TA and TMR here use the operational definitions shown above; they are not retrospective estimates. Empty denominators display “—”. Project reliability uses total met / total promises across closed weeks, not an average of percentages.</p></div></div></>}
function Academy(){const cards=[['01','Master & pull planning','SHOULD','Define milestones with the team. Work backward from the required outcome and describe each trade’s handoff. Agree on who needs what, where and when. This app supports calendar-day finish-to-start handoffs, with zero lag.'],['02','Make-ready planning','CAN','Look ahead six weeks. Check information, materials, labour, equipment, approvals, space and safety. Assign an owner and removal date to every constraint. Ready work has no open constraints and its predecessor handoffs are complete.'],['03','Weekly work planning','WILL','The last planner makes a specific, measurable promise: activity, location, quantity, unit, responsible person and due date. Allocate work first, make the promises, then start the week to freeze the plan.'],['04','Daily commitment management','DID','Record only the quantity completed on that date. Never enter the all-time cumulative value as a daily value. Correct a date by updating that date. The cumulative ledger remains the single source for scope and weekly totals.'],['05','Learn and improve','LEARN','PPC = promises completed in full by their due date ÷ promises made × 100. A 99% complete promise is missed. Work completed late still contributes to scope, but not to on-time PPC. Give each miss a reason and a practical action.'],['06','Carry forward scope','FLOW','When a week closes, unfinished work remains in the activity’s remaining scope. Allocate that remaining scope to a later week and make a new promise. Never create an actual entry or increase total scope just to carry work forward.']];return <><div className="guidegrid">{cards.map(([n,title,stage,body])=><article className="guidecard" key={n}><span className="guidenum">{n}</span><Badge tone="teal">{stage}</Badge><h2>{title}</h2><p>{body}</p></article>)}</div><Panel title="Facilitator’s weekly conversation" detail="Keep the conversation collaborative. Explain the system, not the person."><ol className="guidelist"><li>Review last week’s original promises and on-time completions.</li><li>Identify recurring reasons for variance and assign improvement actions.</li><li>Review the milestone and six-week lookahead together.</li><li>Ask constraint owners what will be removed, and by when.</li><li>Let each last planner promise only the work they can reliably deliver.</li><li>Read back the quantities, dates and owners, then freeze the weekly plan.</li></ol></Panel><div className="callout"><BookOpen size={18}/><div><strong>Method reference</strong><p>Last Planner System® is a registered trademark of the Lean Construction Institute. This independent application uses its should–can–will–did–learn planning cycle. <a href="https://leanconstruction.org/lean-topics/last-planner-system/" target="_blank" rel="noreferrer">Read LCI’s guide ↗</a></p><p>Conference review: confirm your professor’s required TA/TMR definitions, calendars and closeout convention before research use. This version uses Monday–Sunday weeks in India time, calendar-day FS dependencies, and immutable closed weeks.</p></div></div></>}
function parseCSV(text:string):string[][]{const rows:string[][]=[];let row:string[]=[],value='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){value+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(value);value='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(value);rows.push(row);row=[];value='';}else value+=c;}if(quoted)throw Error('CSV contains an unclosed quoted field');if(value||row.length){row.push(value);rows.push(row);}if(rows[0]?.[0])rows[0][0]=rows[0][0].replace(/^\uFEFF/,'');return rows;}
